head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vBndListProcsTpCd = "1";
scwin.vTotAmt = 0;
scwin.vMktactCd;
scwin.vBndApplId, scwin.vIsurCd;
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.arrPar = new Array();

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드처리
        $c.bns.BnsPanelToGroupBox(pnl_Item);
        $c.bns.BnsPanelToGroupBox(pnl_Search);
        $c.bns.BnsPanelToGroupBox(pnl_Group);
        $c.bns.BnsPanelToGroupBox(pnl_Fee);

        // 호출파라미터설정
        scwin.setParam();
        // 발행기관 조회
        scwin.setComboIsurNm();
        // 면제사유코드
        scwin.setComboCode();

        // 상장수수료 및 연부과금 면제사유 비활성화
        cmb_BndListFeeExamCd.setDisabled(true);
        cmb_YafExamCd.setDisabled(true);

        // 가우스헤더 셋팅(그리드 행 복사 대상)
        const sbmOptions = {
            id : "sbm_dts_CopyList",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_CopyList=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20004.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_IsurItem_OnLoadError
 * @description dts_IsurItem 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_IsurItem_OnLoadError = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0002"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20004.dts_IsurItem_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IsurItem_OnLoadCompleted
 * @description dts_IsurItem 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_IsurItem_OnLoadCompleted = function(rowcount) {
    try {
        dts_IsurItem.insertRow(dts_IsurItem.getRowPosition() - 1);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.dts_IsurItem_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name cmb_IsurNm_onselchange
 * @description cmb_IsurNm onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IsurNm_onselchange = function() {
    try {
        scwin.vIsurCd = cmb_IsurNm.BindColVal;
        scwin.listSync();
        scwin.feeSync();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.cmb_IsurNm_onselchange" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        let arrPnl = [pnl_NotAppoint];
        $c.bns.CloseWinArrPnl(rowcount, arrPnl, grd_List1);
        dts_CopyList.removeAll();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_ToRight_onclick
 * @description btn_ToRight 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ToRight_onclick = async function() {
    try {
        await scwin.leftCopy("One");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20004.btn_ToRight_onclick" });
    }
};

/**
 * @method
 * @name btn_ToRightAll_onclick
 * @description btn_ToRightAll 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ToRightAll_onclick = async function() {
    try {
        dts_CopyList.removeAll();
        await scwin.leftCopy("All");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20004.btn_ToRightAll_onclick" });
    }
};

/**
 * @method
 * @name btn_ToLeft_onclick
 * @description btn_ToLeft 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToLeft_onclick = function() {
    try {
        scwin.rightDel("One");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.btn_ToLeft_onclick" });
    }
};

/**
 * @method
 * @name btn_ToLeftAll_onclick
 * @description btn_ToLeftAll 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_ToLeftAll_onclick = function() {
    try {
        scwin.rightDel("All");
        // 총상장금액 설정
        txb_TotAmt.setValue('총상장금액 : ' + 0 + ' 원');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.btn_ToLeftAll_onclick" });
    }
};

/**
 * @method
 * @name img_ListFeeRepayDd_onclick
 * @description img_ListFeeRepayDd 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ListFeeRepayDd_onclick = function() {
    try {
        popUpCalendar2(edt_ListFeeRepayDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.img_ListFeeRepayDd_onclick" });
    }
};

/**
 * @method
