 * @hidden N
 */
scwin.img_AnulfeeRepayDd_onclick = function() {
    try {
        popUpCalendar2(edt_AnulfeeRepayDd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.img_AnulfeeRepayDd_onclick" });
    }
};

/**
 * @method
 * @name cmb_BndListFeePayYn_onselchange
 * @description cmb_BndListFeePayYn onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_BndListFeePayYn_onselchange = function() {
    try {
        if (cmb_BndListFeePayYn.getValue() === "E") {
            cmb_BndListFeeExamCd.setDisabled(true);
            edt_ListFee.setValue('0');
        } else {
            cmb_BndListFeeExamCd.setDisabled(true);
            cmb_BndListFeeExamCd.setValue('');
            if (scwin.vTotAmt !== 0) {
                edt_ListFee.setValue(fn_SetComma($c.bns.fn_ListFeeCall(scwin.vTotAmt)));
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.cmb_BndListFeePayYn_onselchange" });
    }
};

/**
 * @method
 * @name cmb_YafFeePayYn_onselchange
 * @description cmb_YafFeePayYn onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_YafFeePayYn_onselchange = function() {
    try {
        if (cmb_YafFeePayYn.getValue() === "E") {
            cmb_YafExamCd.setDisabled(true);
        } else {
            cmb_YafExamCd.setDisabled(true);
            cmb_YafExamCd.setValue('');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.cmb_YafFeePayYn_onselchange" });
    }
};

/**
 * @method
 * @name dts_CopyList_OnLoadCompleted
 * @description dts_CopyList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_CopyList_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_CopyList.getRowCount() === 0) {
            // 총상장금액 설정
            txb_TotAmt.setValue('총상장금액 : ' + 0 + ' 원');
        }
        edt_ListFee.RightMargin = 5;
        edt_BndAnulfee.RightMargin = 5;
        edt_ListFeeRepayAmt.RightMargin = 5;
        edt_AnulfeeRepayAmt.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.dts_CopyList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_CopyList_OnRowDeleted
 * @description Copy List On Row Deleted 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_CopyList_OnRowDeleted = function(row) {
    try {
        scwin.vTotAmt = dts_CopyList.Sum(2, 1, dts_CopyList.getRowCount());
        // 총상장금액 설정
        txb_TotAmt.setValue('총상장금액 : ' + fn_SetComma(scwin.vTotAmt) + ' 원');
        // 상장수수료 금액 설정
        edt_ListFee.setValue(fn_SetComma($c.bns.fn_ListFeeCall(scwin.vTotAmt)));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.dts_CopyList_OnRowDeleted" });
    }
};

/**
 * @method
 * @name dts_CopyList_OnColumnChanged
 * @description Copy List On Column Changed 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.dts_CopyList_OnColumnChanged = function(row, colid) {
    try {
        scwin.vTotAmt = dts_CopyList.Sum(2, 1, dts_CopyList.getRowCount());
        // 총상장금액 설정
        txb_TotAmt.setValue('총상장금액 : ' + fn_SetComma(scwin.vTotAmt) + ' 원');
        // 상장수수료 금액 설정
        edt_ListFee.setValue(fn_SetComma($c.bns.fn_ListFeeCall(scwin.vTotAmt)));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.dts_CopyList_OnColumnChanged" });
    }
};

/**
 * @method
 * @name btn_FeeReg_onclick
 * @description 「수수료등록」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FeeReg_onclick = async function() {
    try {
        await scwin.insert();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS20004.btn_FeeReg_onclick" });
