};

/**
 * @method
 * @name edt_ListFee_OnKillFocus
 * @description edt_ListFee 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_ListFee_OnKillFocus = function() {
    try {
        edt_ListFee.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.edt_ListFee_OnKillFocus" });
