    }
};

/**
 * @method
 * @name edt_ListFeeRepayAmt_OnKillFocus
 * @description edt_ListFeeRepayAmt 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_ListFeeRepayAmt_OnKillFocus = function() {
    try {
        edt_ListFeeRepayAmt.RightMargin = 5;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS20004.edt_ListFeeRepayAmt_OnKillFocus" });
    }
};

/**
 * @method
 * @name edt_AnulfeeRepayAmt_OnKillFocus
 * @description edt_AnulfeeRepayAmt 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.edt_AnulfeeRepayAmt_OnKillFocus = function() {
    try {
