///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 부모창에서 받은 데이터를 설정한다.
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function() {
    const prt = $c.frame.path("../");
    if (prt !== undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar !== undefined) {
        scwin.fn_GetPar(scwin.arrPar);
        scwin.vMktactCd = scwin.arrPar[0].MKTACT_CD;
    }
};

/**
 * @method
 * @name setComboIsurNm
 * @description 콤보데이터 정의 (그룹지정할 발행기관명)
 * @returns {void}
 * @hidden N
 */
scwin.setComboIsurNm = function() {
    let dsNm = 'BNS_COM_CD';
    let qryId = 'lds.stf.bnscommon.select.listGroupingIsurNmIsuChg';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    $c.bns.fn_SearchBns('ULDBNS2004.xml', dts_IsurItem, dsNm, qryId, param);
};

/**
 * @method
 * @name setComboCode
 * @description 콤보데이터 정의 (채권상장수수료면제사유코드)
 * @returns {void}
 * @hidden N
 */
scwin.setComboCode = function() {
    const arrCid = [];
    arrCid.push({
        cid: '03385',
        cnm: 'cmb_BndListFeeExamCd'
    });
    arrCid.push({
        cid: '03484',
        cnm: 'cmb_YafExamCd'
    });
    $c.bns.fn_SetBnsComboToCode('ULDBNS2004.xml', dts_Temp, arrCid);
};

/**
 * @method
 * @name listSync
 * @description 리스트 데이터를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.listSync = function() {
    let dsNm = 'BNS_GROUPPING_PACK_ISU_INFO';
    let qryId = 'lds.stf.bnscommon.select.listSelectedIsurNmIsuChg';
    let param = '&{P}V_BND_LIST_PROCS_TP_CD=' + scwin.vBndListProcsTpCd;
    param += '&{P}V_MKTACT_CD=' + scwin.vMktactCd;
    param += '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns('ULDBNS2004.xml', dts_List, dsNm, qryId, param);
    let arrPnl = [pnl_NotAppoint];
    $c.bns.ShowWinArrPnl(arrPnl, grd_List1);
};

/**
 * @method
 * @name feeSync
 * @description 수수료 데이터를 조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.feeSync = function() {
    let dsNm = 'BNS_PACK_ANULFEE_INSERT_INFO';
    let qryId = 'lds.stf.bnscommon.select.listSelectedIsurFee';
    let param = '&{P}V_ISUR_CD=' + scwin.vIsurCd;
    $c.bns.fn_SearchBns('ULDBNS2004.xml', dts_InputItem, dsNm, qryId, param);
};

/**
 * @method
 * @name leftCopy
 * @description 그리드 행 복사 (좌 → 우)
 * @param {*} Type Type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.leftCopy = async function(Type) {
    for (let i = 1; i <= dts_List.getRowCount(); i++) {
        if ((Type === 'One') && (dts_List.RowMark(i) === 1)) {
            if (await scwin.copyDuplCheck() === false) return;
            dts_CopyList.insertRow();
            for (let j = 1; j <= dts_List.getTotalCol(); j++) {
                dts_CopyList.setCellData(dts_CopyList.getRowPosition(), j, dts_List.getCellData(i, j));
            }
        }
        if ((Type === 'All')) {
            if (dts_CopyList.getRowCount() !== dts_List.getRowCount()) {
                dts_CopyList.insertRow();
                for (let j = 1; j <= dts_List.getTotalCol(); j++) {
                    dts_CopyList.setCellData(i, j, dts_List.getCellData(i, j));
                }
            }
        }
    }
};

/**
 * @method
 * @name copyDuplCheck
 * @description 그리드 행 복사 시, 중복체크 (return: String)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.copyDuplCheck = async function() {
    const curRowVal = dts_List.getCellData(dts_List.getRowPosition(), "BND_APPL_ID");
    for (let i = 1; i <= dts_CopyList.getRowCount(); i++) {
        if (curRowVal === dts_CopyList.getCellData(i, "BND_APPL_ID")) {
            await $c.win.alert("이미 선택된 종목입니다.");
            return false;
        }
    }
};

/**
 * @method
 * @name rightDel
 * @description 그리드 행 제거
 * @param {*} Type Type
 * @returns {void}
 * @hidden N
 */
scwin.rightDel = function(Type) {
    dts_CopyList.setBroadcast(false);
    for (let i = 1; i <= dts_CopyList.getRowCount(); i++) {
        if ((Type === 'All') || (Type === 'One') && (dts_CopyList.RowMark(i) === 1)) {
            if (Type === 'One') dts_CopyList.removeRow(dts_CopyList.getRowPosition());
            if (Type === 'All') dts_CopyList.removeAll();
        }
    }
    dts_CopyList.setBroadcast(true, true);
};

/**
 * @method
 * @name inputCheck
 * @description 필수 입력 값을 체크한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.inputCheck = async function() {
    if (dts_CopyList.getRowCount() === 0) {
        await $c.win.alert("지정된 종목이 없습니다.");
        return false;
    }
    if (txb_FeeGrpNm.getValue() === '') {
        await $c.win.alert("[그룹명]을 입력하십시오.");
        txb_FeeGrpNm.focus();
        return false;
    }
    // 자리수 체크
    if (!$c.stf.checkMaxLength(txb_FeeGrpNm, txb_FeeGrpNm.maxLength, lbl_FeeGrpNm.outerText)) return false;
    if (!$c.stf.checkMaxLength(txb_MemoContn, 200, '비고(사유)')) return false;
    if (cmb_BndListFeePayYn.getValue() === '') {
        await $c.win.alert("[신규상장수수료 납부여부]를 선택하십시오.");
        return false;
    }
    if (cmb_BndListFeeExamCd.getValue() === "E" && cmb_BndListFeeExamCd.getValue() === '') {
        await $c.win.alert("[신규상장수수료 면제사유를 선택하십시오.");
        return false;
    }
    if (edt_ListFee.getValue() === '') {
        await $c.win.alert("[신규상장수수료 금액]을 입력하십시오.");
        edt_ListFee.focus();
        return false;
    }
    if (cmb_YafFeePayYn.getValue() === '') {
        await $c.win.alert("[연부과금 납부여부]를 선택하십시오.");
        return false;
    }
    if (cmb_YafExamCd.getValue() === "E" && cmb_YafExamCd.getValue() === '') {
        await $c.win.alert("[연부과금 면제사유를 선택하십시오.");
        return false;
    }
    if (edt_BndAnulfee.getValue() === '') {
        await $c.win.alert("[연부과금 수수료 금액]을 입력하십시오.");
        edt_BndAnulfee.focus();
        return false;
    }
    return true;
};

/**
 * @method
 * @name insert
 * @description 상장 수수료 그룹핑 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.insert = async function() {
    if (await scwin.inputCheck() === false) return;
    const vAnswer = confirm('지정된 종목을 수수료 그룹지정 하시겠습니까?');
    if (vAnswer === true) {
        let url = "/bns/ListFeeAndAnulfee.do?method=processPackBndFeeGrpDesign";
        url += "&SCREN_ID=" + 'ULDBNS2004.xml';
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.Action = $c.lc.fn_encodeNSession(url);
        trs_Save.KeyValue = "JSP(I:pInput=dts_InputItem, I:pInput2=dts_CopyList)";
        trs_Save.Post();
    }
};
